(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10),view=document.body.dataset.view;
let demo=localStorage.getItem('mm-crew-mode')==='demo',data={jobs:[],events:[],photos:[],messages:[],notifications:[],members:[]},queue=[],photos=[],locationFix=null,watch=null,syncing=false,filter='all',installPrompt,db;
const uid=()=>demo?'demo':MM.session?.user?.id,states={scheduled:'Scheduled',arrived:'Checked in',in_progress:'In progress',completed:'Completed',blocked:'Needs attention'},office='https://office.mowmatter.com';
const toast=t=>{const e=$('#toast');e.textContent=t;e.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('visible'),5000)},error=e=>toast(e.message||String(e));
const open=html=>{ $('#dialog-content').innerHTML=html;$('#dialog').showModal();},close=()=>$('#dialog').close();$('#close-dialog').onclick=close;
function seed(){return {company:{name:'Greenline Lawn Care'},profile:{id:'demo',name:'Jamie',role:'member'},members:[{user_id:'demo',display_name:'Jamie'}],jobs:Array.from({length:8},(_,i)=>({id:'demo-'+i,assigned_to:'demo',customer_name:['Taylor Reed','Alex Morgan','Jordan Lee','Sam Parker','Casey Brooks','Riley Smith','Avery Lane','Drew Ellis'][i],address:(104+i*8)+' Oak Drive',city:'Palm Coast, FL',service_date:today(),scheduled_time:(8+i)+':00',status:i<2?'completed':'scheduled',services:['Mow','Edge','Blow'],notes:i===2?'Side gate is unlocked. Please close the gate after service. Dog stays indoors.':'Close gates before leaving.',latitude:29.584+i*.001,longitude:-81.207+i*.001,requires_photo:true})),events:[],photos:[],notifications:[],messages:[{id:'sample',actor_id:'office',body:'Good morning. Watch for a loose gate latch at the third stop. Thanks for keeping the route moving.',created_at:new Date().toISOString()}]};}
async function storage(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('mow-crew-v1',1);r.onupgradeneeded=()=>['queue','photos','snapshots'].forEach(n=>r.result.createObjectStore(n,{keyPath:'id'}));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});}
function store(n,op,value){return new Promise((resolve,reject)=>{const tx=db.transaction(n,op==='getAll'||op==='get'?'readonly':'readwrite'),r=tx.objectStore(n)[op](value);let result;r.onsuccess=()=>{result=r.result};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Phone storage unavailable'));});}
async function local(){queue=(await store('queue','getAll')).filter(q=>q.user_id===uid()).sort((a,b)=>a.created_at.localeCompare(b.created_at));photos=(await store('photos','getAll')).filter(p=>p.user_id===uid());}
function visibleJobs(){const jobs=data.jobs.filter(j=>!j.cancelled_at).map(j=>({...j}));for(const q of queue){const j=jobs.find(j=>j.id===q.job_id);if(j){j.status={check_in:'arrived',start:'in_progress',complete:'completed',issue:'blocked'}[q.verb];j.pending=true;j.queue_error=q.error;}}return jobs;}
function job(){const requested=new URLSearchParams(location.search).get('id');if(requested)return visibleJobs().find(j=>j.id===requested);return visibleJobs().find(j=>j.status==='in_progress')||visibleJobs().find(j=>j.status!=='completed');}
const pill=j=>`<span class="pill ${esc(j.status)}">${esc(states[j.status])}${j.pending?' · Pending sync':''}</span>`;
const cardList=jobs=>`<ul class="job-list">${jobs.map((j,i)=>`<li><span class="number">${j.status==='completed'?'✓':i+1}</span><a href="job.html?id=${encodeURIComponent(j.id)}"><b>${esc(j.address)}</b><small>${esc(j.customer_name)} · ${esc(j.services.join(' / '))}</small></a>${pill(j)}</li>`).join('')||'<li>No jobs assigned for this view.</li>'}</ul>`;
function banner(){return demo?'<div class="demo-bar">SAMPLE WORKSPACE · Actions stay on this device. <a href="more.html">Switch to your real account</a></div>':'';}
function status(){ $('#connection').textContent=demo?'Demo mode':queue.length?queue.length+(queue.some(q=>q.error)?' · Needs attention':' pending'):navigator.onLine?'Online':'Offline';}
function render(){status();if(!demo&&!MM.session){auth();return}let jobs=visibleJobs(),daily=jobs.filter(j=>j.service_date===today()),next=daily.find(j=>j.status==='in_progress')||daily.find(j=>j.status!=='completed'),done=daily.filter(j=>j.status==='completed').length;const head=(title,sub)=>`<div class="page-head"><div><p class="eyebrow">${esc(sub||data.company?.name||'CREW WORKSPACE')}</p><h1>${title}</h1></div><span class="pill">${esc(new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}))}</span></div>`;
let html=banner();if(!data.company&&!demo){html+=`<div class="card empty"><h2>You’re signed in.</h2><p>Your owner needs to assign this email to a crew in Office before jobs appear.</p><p>${esc(MM.session.user.email)}</p><a class="button primary" href="${office}/crew-live.html">Open Office setup</a><button class="button" data-action="refresh">Check assignment</button></div>`;}
else if(view==='index'){html+=head('Let’s get it cut.',`GOOD MORNING, ${data.profile?.name||'CREW'}`)+`<div class="stats"><div><strong>${done}/${daily.length}</strong><span>Jobs complete</span></div><div><strong>${daily.length-done}</strong><span>Still to cut</span></div><div><strong>${queue.length}</strong><span>Pending sync</span></div></div><div class="split"><section class="card next-job"><p class="eyebrow">${next?'YOUR NEXT STOP':'ALL HANDLED'}</p><h2>${next?esc(next.address):'Your route is clear.'}</h2><p>${next?esc(next.customer_name)+' · '+esc(next.city):'No remaining jobs assigned for today.'}</p>${next?`<div class="notice" style="color:#09271e">${esc(next.notes)}</div>${pill(next)}<a class="button primary full" href="job.html?id=${encodeURIComponent(next.id)}">${next.status==='in_progress'?'Continue job':'Open job & check in'} →</a>`:''}<button class="button secondary full" data-action="gps">${watch!==null?'Location prompts enabled':'Enable location check-in'}</button><p class="help">Location prompts work while this app is open. You always confirm start and completion.</p></section><section class="card"><h2>Today’s route</h2>${cardList(daily)}<a class="button full" href="route.html">View entire route</a></section></div>`;}
else if(view==='route'){html+=head('One stop at a time.')+`<div class="notice">Assigned stop order. Live traffic optimization is not connected yet.</div><button class="button" data-action="gps">Enable location prompts</button><section class="card">${cardList(daily)}</section><figure class="card map-card"><img src="neighborhood-map.jpg" alt="Illustrative neighborhood map"><figcaption>Illustrative map. Open a job to navigate to its actual address.</figcaption></figure>`;}
else if(view==='jobs'){html+=head('Your jobs.')+`<div class="toolbar">${['all','scheduled','in_progress','completed','blocked'].map(s=>`<button class="filter ${filter===s?'active':''}" data-filter="${s}">${states[s]||'All'}</button>`).join('')}</div><section class="card">${cardList(jobs.filter(j=>filter==='all'||j.status===filter))}</section>`;}
else if(view==='job'){const j=job();if(!j){html+='<section class="card empty"><h2>No job here yet.</h2><a class="button" href="jobs.html">Back to jobs</a></section>';}else{const p=photos.filter(p=>p.job_id===j.id),remote=(data.photos||[]).filter(p=>p.job_id===j.id);html+=head(esc(j.address),j.customer_name)+`<div class="split"><section class="card">${pill(j)}<p class="muted" style="margin-top:12px">${esc(j.city)} · ${esc(j.service_date)} · ${esc(j.scheduled_time?.slice(0,5))}</p><div class="notice"><strong>Before you start</strong><br>${esc(j.notes||'No special access instructions.')}</div><p>${esc(j.services.join(' · '))}</p>${j.queue_error?`<p class="error">Sync needs attention: ${esc(j.queue_error)}</p>`:''}<a class="button full" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(j.address+', '+j.city)}&dir_action=navigate">Navigate to this lawn ↗</a><h3 style="margin-top:22px">Proof of a job well done</h3><p class="help">${j.requires_photo?'A completion photo is required.':'Photos are optional.'} Photos upload privately to Office when online.</p><div class="photo-grid">${remote.map(p=>`<img src="${esc(p.url)}" alt="Job completion proof">`).join('')}${p.map(p=>`<img src="${URL.createObjectURL(p.blob)}" alt="Saved proof photo">`).join('')}${j.status!=='completed'?'<label class="photo-add">+ Add photo<input id="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label>':''}</div></section><section class="card"><h2>Job activity</h2><ul class="timeline">${[...(data.events||[]).filter(e=>e.job_id===j.id),...queue.filter(e=>e.job_id===j.id).map(e=>({...e,action:e.verb,pending:true}))].sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(e=>`<li>${esc({check_in:'Checked in',start:'Job started',complete:'Job complete',issue:'Issue reported'}[e.action])}<small>${esc(new Date(e.created_at).toLocaleTimeString())}${e.pending?' · Saved on phone, pending sync':''}</small></li>`).join('')||'<li>No activity yet.</li>'}</ul><h3 style="margin-top:24px">Homeowner updates</h3><p class="help">${demo?'Demo previews only. No messages are sent.':'Start and completion updates appear in Office. Email updates require customer consent, an email address and a connected provider. SMS is disabled.'}</p>${(data.notifications||[]).filter(n=>n.job_id===j.id).map(n=>`<div class="message">${esc(n.body)}<small>${esc(({sent:'Email accepted by Resend',failed:'Email failed · Owner can retry',pending_provider:'Email provider not connected · Not sent',held_no_consent:'Not sent · Customer consent required',held_no_contact:'Not sent · Customer contact required',demo_preview:'Sample preview · Not sent'})[n.status]||n.status.replaceAll('_',' '))}</small></div>`).join('')}</section></div>${j.status!=='completed'?`<div class="job-actionbar"><button class="button" data-action="issue">Report issue</button><button class="button primary" data-action="${j.status==='in_progress'?'finish':'arrive'}">${j.status==='in_progress'?'Complete job':j.status==='arrived'?'Start job':'Check in / Start'}</button></div>`:''}`;}}
else if(view==='messages'){html+=head('Keep Office in the loop.')+`<section class="card"><h2>Team messages</h2>${(data.messages||[]).slice().reverse().map(m=>`<div class="message ${m.actor_id===uid()?'mine':''}"><small>${esc(data.members?.find(u=>u.user_id===m.actor_id)?.display_name||'Team')} · ${esc(new Date(m.created_at).toLocaleTimeString())}</small>${esc(m.body)}</div>`).join('')||'<p class="muted">No team messages yet.</p>'}<form id="message-form" class="form"><label>Message to your team<textarea name="text" required maxlength="2000" placeholder="Gate issue? Running late? Let Office know."></textarea></label><button class="button primary full">Send message</button><p class="help">Internal team messages. Homeowners do not see this conversation.</p></form></section>`;}
else{html+=head('Ready for the field.')+`<section class="card"><h2>${esc(data.profile?.name||'Your account')}</h2><p>${esc(data.company?.name||'Awaiting assignment')}</p><p class="help">${demo?'Sample crew account':esc(data.profile?.email||MM.session.user.email)}</p><div class="menu-list"><button data-action="sync">Sync updates <span>${queue.length} pending →</span></button><button data-action="gps">Location check-in <span>${watch!==null?'On':'Off'} →</span></button><button data-action="install">Add app to home screen →</button><a href="${office}/crew-live.html">Open Office →</a><button data-action="help">Field help →</button><button data-action="logout">${demo?'Sign in to your real account':'Sign out'} →</button></div></section><div class="notice">This is a mobile web app. Location is captured only while it is open and with your permission. Job completion always needs your confirmation.</div>`;}
$('#main').innerHTML=html;bind();}
function auth(){ $('#main').innerHTML=`<section class="card auth"><p class="eyebrow">MOW MATTER CREW</p><h1>Less typing.<br>More getting it done.</h1><p class="muted">Your assigned lawns, check-in and completion proof in one field workspace.</p><p class="help legal-support-text"><a href="https://mowmatter.com/terms.html">Terms</a> · <a href="https://mowmatter.com/privacy.html">Privacy</a> · <a href="https://mowmatter.com/contact.html">Support</a></p><form id="auth-form" class="form"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><p id="auth-error" class="error" role="status"></p><button class="button primary full" name="mode" value="login">Sign in to your crew</button><button class="button full" style="margin-top:10px" name="mode" value="signup">Create an account</button></form><p class="help" style="margin-top:15px">After email confirmation, your owner assigns you from Office.</p><div class="actions" style="margin:15px 0"><button class="button" id="forgot">Forgot password?</button><button class="button" id="resend">Resend confirmation</button></div><button class="button dark full" id="demo">Explore the sample route →</button></section>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.submitter;b.disabled=true;try{if(b.value==='signup'){await MM.signUp(f.get('email'),f.get('password'));$('#auth-error').textContent='Check your email to confirm the account, then return here to sign in.';}else{await MM.signIn(f.get('email'),f.get('password'));demo=false;localStorage.setItem('mm-crew-mode','live');await load();}}catch(err){$('#auth-error').textContent=err.message}finally{b.disabled=false}};$('#forgot').onclick=()=>emailHelp('recover');$('#resend').onclick=()=>emailHelp('resend');$('#demo').onclick=async()=>{demo=true;localStorage.setItem('mm-crew-mode','demo');await load();}; }
function emailHelp(kind){open(`<h2>${kind==='recover'?'Recover your account.':'Confirm your email.'}</h2><form id="email-help" class="form"><label>Email<input name="email" type="email" required autocomplete="email"></label><p role="status"></p><button class="button primary full">Send email</button></form>`);$('#email-help').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const email=new FormData(e.target).get('email');if(kind==='recover')await MM.resetPassword(email);else await MM.resend(email);$('#email-help [role="status"]').textContent='If eligible, an email has been requested. Check your inbox and spam folder.'}catch(err){$('#email-help [role="status"]').textContent=err.message}finally{b.disabled=false}};}
function recoveryForm(){$('#main').innerHTML='<section class="card auth"><h1>Choose a new password.</h1><form id="recovery" class="form"><label>New password<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label>Confirm password<input name="confirm" type="password" minlength="8" required autocomplete="new-password"></label><p role="status"></p><button class="button primary full">Save new password</button></form></section>';$('#recovery').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=new FormData(e.target);if(f.get('password')!==f.get('confirm'))throw Error('Passwords must match');await MM.updatePassword(f.get('password'));demo=false;localStorage.setItem('mm-crew-mode','live');await load()}catch(err){$('#recovery [role="status"]').textContent=err.message}finally{b.disabled=false}};}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action).catch(error));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});if($('#photo'))$('#photo').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const blob=await compress(f),p={id:id(),job_id:job().id,user_id:uid(),blob};await store('photos','put',p);await local();render();toast('Photo saved on this phone.');}catch(err){error(err)}};if($('#message-form'))$('#message-form').onsubmit=async e=>{e.preventDefault();const text=new FormData(e.target).get('text');try{if(demo){data.messages.push({id:id(),actor_id:'demo',body:text,created_at:new Date().toISOString()});saveDemo();render();}else{if(!navigator.onLine)throw Error('You’re offline. Keep this draft and send when connected.');await MM.api({action:'message',text});await load();}}catch(err){error(err)}};}
function saveDemo(){localStorage.setItem('mm-crew-demo-v1',JSON.stringify(data));}
async function load(){await MM.ready;if(MM.recovery){recoveryForm();return}await local();if(demo){try{data=JSON.parse(localStorage.getItem('mm-crew-demo-v1'))||seed()}catch{data=seed()}saveDemo();render();return}if(!MM.session){render();return}try{data=await MM.api({action:'list'});await store('snapshots','put',{id:uid(),data});}catch(err){const saved=await store('snapshots','get',uid());if(saved){data=saved.data;toast('Showing saved jobs. Updates will sync when connected.');}else{error(err)}}render();}
async function compress(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>20000000)throw Error('Use a JPG, PNG or WebP photo under 20 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.8));if(!blob||blob.size>5242880)throw Error('Photo is too large. Try a smaller picture.');return blob;}
async function enqueue(j,verb,details){const event={id:id(),event_id:null,job_id:j.id,user_id:uid(),verb,details,created_at:new Date().toISOString()};event.event_id=event.id;if(demo){j=data.jobs.find(x=>x.id===j.id);j.status={check_in:'arrived',start:'in_progress',complete:'completed',issue:'blocked'}[verb];data.events.push({...event,action:verb});if(['start','complete'].includes(verb))data.notifications.push({job_id:j.id,body:verb==='start'?`Good news—your lawn care is starting at ${j.address}.`:`Fresh cut. Clean edges. Your lawn care at ${j.address} is complete.`,status:'demo_preview'});saveDemo();render();toast('Demo updated. No homeowner message sent.');return}await store('queue','put',event);await local();render();toast('Saved on phone. Syncing to Office…');await sync();}
async function sync(){if(demo){toast('Sample actions stay on your phone.');return}if(syncing||!MM.session)return;if(!navigator.onLine){toast('Offline. Your updates are saved on this phone.');return}syncing=true;let hadUpdates=false;const blocked=new Set();try{await local();hadUpdates=queue.length>0;for(const q of queue){if(blocked.has(q.job_id))continue;try{for(const p of photos.filter(p=>p.job_id===q.job_id&&!p.uploaded)){const f=new FormData();f.append('job_id',p.job_id);f.append('photo_id',p.id);f.append('file',p.blob,'proof.jpg');await MM.api(f);p.uploaded=true;await store('photos','put',p);}await MM.api({action:'transition',job_id:q.job_id,event_id:q.event_id,verb:q.verb,details:q.details});await store('queue','delete',q.id);}catch(err){q.error=err.message||'Update could not sync';await store('queue','put',q);blocked.add(q.job_id);}}await load();if(blocked.size)toast('Some work needs attention. Open sync status to review it.');else if(hadUpdates&&!queue.length)toast('Job updates synced to Office.');}catch(err){error(err);await local();render();}finally{syncing=false;status();}}
function syncReview(){const failed=[...new Set(queue.filter(q=>q.error).map(q=>q.job_id))];open(`<h2>Your work, accounted for.</h2><p>${demo?'You’re in the sample workspace.':navigator.onLine?'Connection available.':'You’re offline.'}</p><p>${queue.length} job updates waiting for Office.</p>${failed.map(jid=>{const q=queue.find(q=>q.job_id===jid&&q.error),j=data.jobs.find(j=>j.id===jid);return `<section class="notice"><strong>${esc(j?.address||'Job no longer in your assigned route')}</strong><p class="error">${esc(q.error)}</p><button class="button" data-review-job="${esc(jid)}">Review local updates</button></section>`}).join('')}<p class="help">Pending actions and photos stay on this phone. Retrying keeps the same identifiers to avoid duplicates.</p><button class="button primary full" id="sync-now">Retry pending updates</button>`);$('#sync-now').onclick=async()=>{close();await sync();};document.querySelectorAll('[data-review-job]').forEach(b=>b.onclick=()=>discardReview(b.dataset.reviewJob));}
function discardReview(jid){if(syncing){toast('Wait for the current sync to finish.');return}const pending=queue.filter(q=>q.job_id===jid),proof=photos.filter(p=>p.job_id===jid&&!p.uploaded);if(!pending.some(q=>q.error)){syncReview();return}open(`<h2>Discard unsynced work?</h2><p>This removes ${pending.length} local job update${pending.length===1?'':'s'} and ${proof.length} photo${proof.length===1?'':'s'} that have not uploaded for this job.</p><p>It does not undo work already recorded in Office. Check with your owner before discarding real work.</p><div class="actions"><button class="button" id="keep-updates">Keep my updates</button><button class="button" id="discard-updates">Discard local updates</button></div>`);$('#keep-updates').onclick=syncReview;$('#discard-updates').onclick=async()=>{if(syncing){toast('Wait for sync to finish.');return}const b=$('#discard-updates');b.disabled=true;try{for(const q of pending)await store('queue','delete',q.id);for(const p of proof)await store('photos','delete',p.id);await local();close();await load();toast('Local updates discarded. Office records are unchanged.');}catch(err){error(err);b.disabled=false}};}

function distance(a,b){const r=Math.PI/180,dlat=(b.latitude-a.latitude)*r,dlng=(b.longitude-a.longitude)*r,t=Math.sin(dlat/2)**2+Math.cos(a.latitude*r)*Math.cos(b.latitude*r)*Math.sin(dlng/2)**2;return 6371000*2*Math.atan2(Math.sqrt(t),Math.sqrt(1-t));}
const prompted=new Set();function gps(){if(watch!==null){toast('Location prompts are already enabled.');return}if(!navigator.geolocation)throw Error('Location is unavailable. Use manual check-in.');watch=navigator.geolocation.watchPosition(p=>{locationFix={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,captured_at:new Date(p.timestamp).toISOString()};if(locationFix.accuracy>100||$('#dialog').open||document.hidden)return;for(const j of visibleJobs().filter(j=>j.service_date===today()&&j.latitude!=null&&j.longitude!=null)){const d=distance(locationFix,j),key=j.id+':'+j.status;if(prompted.has(key))continue;if(d<=150&&['scheduled','blocked'].includes(j.status)){prompted.add(key);open(`<div class="dialog-icon">⌖</div><h2>You’re at ${esc(j.address)}.</h2><p>Ready to check in? Start only when your crew is ready to work.</p><a class="button primary full" href="job.html?id=${encodeURIComponent(j.id)}">Open job & confirm</a>`);break}if(d>300&&j.status==='in_progress'){prompted.add(key);open(`<h2>Finished at ${esc(j.address)}?</h2><p>Confirm the checklist and completion photo before closing this job.</p><a class="button primary full" href="job.html?id=${encodeURIComponent(j.id)}">Review completion</a>`);break}}status();},()=>{if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;locationFix=null;toast('Location unavailable. Manual check-in is still available.');status();},{enableHighAccuracy:true,maximumAge:10000,timeout:20000});toast('Location prompts enabled while the app is open.');}
function capture(j){if(locationFix&&Date.now()-Date.parse(locationFix.captured_at)<120000&&locationFix.accuracy<=100&&j.latitude!=null&&distance(locationFix,j)<=150)return {location:locationFix,manual:false};return null;}
async function action(a){const j=job();if(a==='refresh'){await load();return}if(a==='sync'){await sync();return}if(a==='gps'){gps();return}if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else open('<h2>Keep Crew one tap away.</h2><p>On iPhone: open in Safari, tap Share, then Add to Home Screen.</p><p>On Android: use your browser’s Install app or Add to Home screen menu.</p>');return}if(a==='help'){open('<h2>Field help</h2><p>Check the address and gate notes. Confirm Start job when work begins. Finish every listed service, attach proof, then confirm completion.</p><p>Offline updates remain on this phone until Office acknowledges them. Keep the app open to sync.</p><p>Location never starts or completes work without your confirmation.</p>');return}if(a==='logout'){if(queue.length)throw Error('Sync pending job updates before signing out.');if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;}demo=false;localStorage.setItem('mm-crew-mode','live');await MM.signOut();data={jobs:[],events:[],photos:[],messages:[],notifications:[]};queue=[];photos=[];render();return}if(!j)throw Error('Open an assigned job first.');
if(a==='arrive'){const fix=capture(j);open(`<div class="dialog-icon">⌖</div><h2>${j.status==='arrived'?'Ready to start?':'You’re here. Let’s get started.'}</h2><p>${esc(j.address)}</p><form id="start-form" class="form">${fix?'<p class="success">Location captured near this lawn.</p>':'<label>Manual check-in reason<input name="reason" required minlength="3" maxlength="200" placeholder="GPS unavailable; address checked"></label>'}<p class="help">Starting records the job in Office and queues the homeowner update. Message delivery requires a connected provider.</p><div class="actions">${j.status==='arrived'?'':'<button class="button" name="verb" value="check_in">Check in only</button>'}<button class="button primary" name="verb" value="start">Confirm Start job</button></div></form>`);$('#start-form').onsubmit=async e=>{e.preventDefault();const details=fix||{manual:true,manual_reason:new FormData(e.target).get('reason'),...(locationFix?{location:locationFix}:{})};const verb=e.submitter.value;close();await enqueue(j,verb,details);};}
if(a==='finish'){if(j.status!=='in_progress')throw Error('Start the job before completing it.');open(`<div class="dialog-icon">✓</div><h2>A lawn worth coming home to.</h2><p>${esc(j.address)}</p><form id="finish-form"><div class="checklist">${j.services.map(s=>`<label><input type="checkbox" name="task" value="${esc(s)}" required>${esc(s)} complete</label>`).join('')}</div><p class="help">${j.requires_photo?'A proof photo must be saved before completion.':'Completion photos are optional.'} Completion syncs to Office; homeowner delivery awaits the message provider.</p><button class="button primary full">Confirm Job Complete</button></form>`);$('#finish-form').onsubmit=async e=>{e.preventDefault();if(j.requires_photo&&!photos.some(p=>p.job_id===j.id)&&!(data.photos||[]).some(p=>p.job_id===j.id)){toast('Add a completion photo on the job first.');return}const details={completed_tasks:new FormData(e.target).getAll('task'),...(locationFix?{location:locationFix}:{})};close();await enqueue(j,'complete',details);};}
if(a==='issue'){open(`<h2>Flag it for Office.</h2><form id="issue-form" class="form"><label>What’s blocking the job?<textarea name="reason" minlength="3" maxlength="1000" required placeholder="Locked gate, unsafe conditions, equipment issue…"></textarea></label><button class="button primary full">Save issue & pause job</button></form>`);$('#issue-form').onsubmit=async e=>{e.preventDefault();const reason=new FormData(e.target).get('reason');close();await enqueue(j,'issue',{reason,...(locationFix?{location:locationFix}:{})});};}}
$('#connection').onclick=syncReview;
window.addEventListener('online',()=>sync());window.addEventListener('offline',status);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});document.addEventListener('visibilitychange',()=>{locationFix=null;if(!document.hidden&&!demo&&MM.session)sync()});
(async()=>{try{await MM.ready;await storage();await load();if(!demo&&MM.session)await sync();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}catch(err){$('#main').innerHTML=`<section class="card"><h2>Phone storage is unavailable.</h2><p>${esc(err.message)}</p><p>Enable browser storage for reliable offline check-in and photos.</p></section>`}})();
setInterval(()=>{if(!document.hidden&&!demo&&MM.session&&navigator.onLine&&!syncing&&!$('#dialog').open&&!$('#message-form textarea')?.value)sync();},30000);
if(navigator.modelContext?.registerTool)navigator.modelContext.registerTool({name:'view_assigned_jobs',description:'Read the current assigned jobs and sync status. No job changes.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({demo,jobs:visibleJobs().map(j=>({id:j.id,address:j.address,status:j.status,pending:!!j.pending})),pending_updates:queue.length})}]})});
})();
